    public static function supportInterval_roundUnit($host, $unit, $precision, $function)
    {
        $fn = \Closure::bind(function ($unit, $precision, $function) {

        $base = CarbonImmutable::parse('2000-01-01 00:00:00', 'UTC')
            ->roundUnit($unit, $precision, $function);
        $next = $base->add($this);
        $inverted = $next < $base;

        if ($inverted) {
            $next = $base->sub($this);
        }

        $this->copyProperties(
            $next
                ->roundUnit($unit, $precision, $function)
                ->diffAsCarbonInterval($base)
        );

        return $this->invert($inverted);

        }, $host, "Carbon\\CarbonInterval");

        return $fn($unit, $precision, $function);
    }

